change_filament_gcode:
{if toolchange_count > 1}
SET_VELOCITY_LIMIT ACCEL=[travel_acceleration]
{if !purge_in_prime_tower || wipe_tower_type != "type2" || print_sequence == "by object"}
T[next_extruder]
_GOTO_TRASH
{if flush_length > 0}
SET_FAN_SPEED FAN=fanM106 SPEED=0
_DISABLE_SENSOR
; FLUSH_START
{if flush_length_1 == 0}
G1 E2 F{min(old_filament_e_feedrate, new_filament_e_feedrate) / 2}
G1 E{flush_length + old_retract_length_toolchange - 2} F{min(old_filament_e_feedrate, new_filament_e_feedrate)}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
G1 E-1 F{new_filament_e_feedrate / 2}
_SBROS_TRASH
SET_FAN_SPEED FAN=fanM106 SPEED=0
{else}
G1 E2 F{min(old_filament_e_feedrate, new_filament_e_feedrate) / 2}
G1 E{flush_length_1 + old_retract_length_toolchange - 2} F{min(old_filament_e_feedrate, new_filament_e_feedrate)}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
G1 E-1 F{new_filament_e_feedrate / 2}
_SBROS_TRASH
SET_FAN_SPEED FAN=fanM106 SPEED=0
{if flush_length_2 > 0}
_GOTO_TRASH
G1 E2 F{new_filament_e_feedrate / 2}
G1 E{flush_length_2 - 1} F{new_filament_e_feedrate}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
G1 E-1 F{new_filament_e_feedrate / 2}
_SBROS_TRASH
SET_FAN_SPEED FAN=fanM106 SPEED=0
{endif}
{if flush_length_3 > 0}
_GOTO_TRASH
G1 E2 F{new_filament_e_feedrate / 2}
G1 E{flush_length_3 - 1} F{new_filament_e_feedrate}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
G1 E-1 F{new_filament_e_feedrate / 2}
_SBROS_TRASH
SET_FAN_SPEED FAN=fanM106 SPEED=0
{endif}
{if flush_length_4 > 0}
_GOTO_TRASH
G1 E2 F{new_filament_e_feedrate / 2}
G1 E{flush_length_4 - 1} F{new_filament_e_feedrate}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
G1 E-1 F{new_filament_e_feedrate / 2}
_SBROS_TRASH
SET_FAN_SPEED FAN=fanM106 SPEED=0
{endif}
{endif}
{if 1 - new_retract_length_toolchange < -2}
G1 E-2 F{new_filament_e_feedrate / 2}
G1 E{1 - new_retract_length_toolchange + 2} F{new_filament_e_feedrate}
{endif}
{if 1 - new_retract_length_toolchange >= -2 and 1 - new_retract_length_toolchange < 0}
G1 E{1 - new_retract_length_toolchange} F{new_filament_e_feedrate / 2}
{endif}
{if 1 - new_retract_length_toolchange > 0 and 1 - new_retract_length_toolchange <= 2}
G1 E{1 - new_retract_length_toolchange} F{new_filament_e_feedrate / 2}
{endif}
{if 1 - new_retract_length_toolchange > 2}
G1 E2 F{new_filament_e_feedrate / 2}
G1 E{1 - new_retract_length_toolchange - 2} F{new_filament_e_feedrate}
{endif}
; FLUSH_END
_ENABLE_SENSOR
{else}
SET_FAN_SPEED FAN=fanM106 SPEED=1
G4 P4000
M400
_SBROS_TRASH
{endif}
{if layer_num < close_fan_the_first_x_layers[next_extruder]}
SET_FAN_SPEED FAN=fanM106 SPEED=0
{elsif layer_num >= full_fan_speed_layer[next_extruder] - 1}
SET_FAN_SPEED FAN=fanM106 SPEED={ fan_min_speed[next_extruder] / 100}
{else}
SET_FAN_SPEED FAN=fanM106 SPEED={ fan_min_speed[next_extruder] * (layer_num - close_fan_the_first_x_layers[next_extruder] + 1) / (full_fan_speed_layer[next_extruder] - close_fan_the_first_x_layers[next_extruder]) / 100}
{endif}
G1 X{((x_after_toolchange + 22) % 264) - 22} Y{242 - ((242 - y_after_toolchange) % 264)} F18000
G1 Z{z_after_toolchange}
{else}
T[next_extruder]
{endif}
{if layer_num == 0}
SET_VELOCITY_LIMIT ACCEL=[initial_layer_acceleration]
{else}
SET_VELOCITY_LIMIT ACCEL=[default_acceleration]
{endif}
{else}
T[next_extruder]
{endif}

machine_start_gcode:
RESPOND MSG="Pre-Processing purge mode results:"
{if purge_in_prime_tower && wipe_tower_type == "type2" && print_sequence == "by layer"}
RESPOND MSG="Purge in prime tower option enabled. Using 'nopoop' mode."
SAVE_VARIABLE VARIABLE=use_trash_on_print VALUE=0
{else}
{if print_sequence == "by layer"}
RESPOND MSG="Purge in prime tower option disabled. Using 'slicer-controlled poop' mode."
{else}
RESPOND MSG="Using 'slicer-controlled poop' mode due to print-by-object mode."
{endif}
SAVE_VARIABLE VARIABLE=use_trash_on_print VALUE=2
{endif}
START_PRINT EXTRUDER_TEMP=[nozzle_temperature_initial_layer] BED_TEMP=[bed_temperature_initial_layer_single]
SET_PRINT_STATS_INFO TOTAL_LAYER=[total_layer_count]
